// GetLivez Report that the process is running
//
// Succeeds whenever the process can serve HTTP. It never checks
// dependencies, so a database outage does not restart every pod.
//
// Corresponds with GET /livez (the `GetLivez` operationId).
func (c *Client) GetLivez(ctx context.Context, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewGetLivezRequest(c.Server)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

// GetReadyz Report whether the server can take traffic
